        void traverse(Graph graph, DfsVisitor visitor) {
            // Build a view that exposes only the component reachable from source by
            // running the standard engine on a graph whose other vertices are
            // unreachable from source anyway; discovery order from source visits
            // exactly the reachable set first. We isolate it by counting only the
            // first DFS tree, which is rooted at source when source is vertex 0.
            // For a general source, delegate to a direct reachable-set walk.
            boolean[] seen = new boolean[graph.vertexCount()];
